import hashlib,json,runpy,subprocess
from pathlib import Path
root=Path.cwd()
checker=root/'docs/evidence/checks/s1-check.py'
paths=[checker,root/'docs/report-rule-consolidation.md',root/'src/orze/engine/rebuild_state.py',root/'src/orze/reporting/evidence.py',root/'tests/test_report_rule_consolidation.py',root.parent/'orze-pro/src/orze_pro/agents/research_context.py',root.parent/'orze-pro/tests/test_report_rule_consolidation.py']
def hashes():
 return {str(p.relative_to(root.parent)):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths}
before=hashes()
assert before['orze/docs/evidence/checks/s1-check.py']=='139621de658f450f9cdbd1471f1f95bbc29153b473839b2c5e17d589acf00211'
m=runpy.run_path(str(checker),run_name='s1_independent_helper_review')
footer=m['footer']; junit=m['junit_cases']
negative={}
def reject(name,fn):
 try:
  fn()
 except (AssertionError,KeyError,ValueError):
  negative[name]='rejected'
 else:
  raise AssertionError('negative control accepted: '+name)
def log(output,passed=4260,failed=0,skipped=7,code=0):
 return lambda:footer([{'output':output,'exit_code':code}],passed,failed,skipped)
reject('old_counts_in_body_wrong_final',log('previous: 4260 passed, 7 skipped\n===== 1 passed in 1.00s =====\n'))
reject('unexpected_failed_despite_exit0',log('===== 2 failed, 4260 passed, 7 skipped in 1.00s =====\n'))
reject('baseline_counts_in_unrelated_body',log('history: 22 passed\nexample: 2 failed\n===== 1 failed in 1.00s =====\n',22,2,0,1))
reject('two_summary_lines',log('4260 passed, 7 skipped in 1.00s\n4260 passed, 7 skipped in 2.00s\n'))
reject('unexpected_error',log('4260 passed, 7 skipped, 1 error in 1.00s\n'))
reject('duplicated_count_label',log('4260 passed, 4260 passed, 7 skipped in 1.00s\n'))
reject('truncated_log',log('truncated output\n4260 passed, 7 skipped in 1.00s\n'))
reject('nonfinal_summary',log('4260 passed, 7 skipped in 1.00s\ntrailing non-summary text\n'))
def xml(body,tests=2,skipped=0):
 return ('<testsuites><testsuite tests="'+str(tests)+'" failures="0" errors="0" skipped="'+str(skipped)+'">'+body+'</testsuite></testsuites>').encode()
def case(name,child=''):
 return '<testcase classname="tests.test_report_rule_consolidation" name="'+name+'">'+child+'</testcase>'
reject('junit_duplicate_identity',lambda:junit(xml(case('same')+case('same')),2,0))
reject('junit_failure_body',lambda:junit(xml(case('a','<failure/>')+case('b')),2,0))
reject('junit_error_body',lambda:junit(xml(case('a','<error/>')+case('b')),2,0))
reject('junit_unreported_skip',lambda:junit(xml(case('a','<skipped/>')+case('b')),2,0))
reject('junit_multiple_skips_one_case',lambda:junit(xml(case('a','<skipped/><skipped/>')+case('b'),skipped=2),0,2))
baseline=json.loads((root/'docs/evidence/2026-09-11-s1-report-rules-baseline.json').read_bytes())
positives={}
for repo,count in [('core',70),('pro',60)]:
 out=footer(baseline['existing_neighborhood'][repo],count)
 positives['actual_baseline_neighborhood_'+repo]=out.rstrip().splitlines()[-1]
for repo,passed in [('core',22),('pro',2)]:
 out=footer(baseline['new_tests'][repo]['chunks'],passed,failed=2)
 positives['actual_baseline_new_tests_'+repo]=out.rstrip().splitlines()[-1]
for repo,passed in [('pro',978),('paired',60)]:
 p=root/('docs/evidence/runs/s1-'+repo+'-junit.xml')
 raw=p.read_bytes(); cases=junit(raw,passed,0)
 new=[c for c in cases if c.attrib['classname'].split('.')[-1]=='test_report_rule_consolidation']
 if repo=='pro':
  assert len(new)==4 and all(c.find('skipped') is None for c in new)
 positives['actual_junit_'+repo]={'sha256':hashlib.sha256(raw).hexdigest(),'bytes':len(raw),'unique_cases':len(cases),'new_cases':len(new)}
positive_synthetic=footer([{'output':'===== 4260 passed, 7 skipped, 1 warning in 1.00s =====\n','exit_code':0}],4260,skipped=7)
extra='docs/evidence/checks/v1-07b-domain-check.py'
old=subprocess.check_output(['git','show',m['BASE']['core']+':'+extra])
assert hashlib.sha256(old).digest()==hashlib.sha256((root/extra).read_bytes()).digest()
structure=m['structural_checks']()
after=hashes(); assert before==after
print(json.dumps({'checker_sha256':hashlib.sha256(checker.read_bytes()).hexdigest(),'negative_controls':negative,'negative_count':len(negative),'actual_positive_controls':positives,'synthetic_expected_footer':positive_synthetic.strip(),'extra_baseline_blob_exact':True,'structural_checks':structure,'pre_post_exact':before==after,'pre_post_sha256':before,'main_invoked':False,'workers_or_tests_run':False},sort_keys=True))
